import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { expect, test } from "vitest";
import { initSync, algo_version as webAlgoVersion } from "../../../backend/rust_wasm_module/pkg/rust_wasm_module.js";
import { wasm } from "./wasmNode";

// The worker uses pkg/ (web target), tests and benchmarks use pkg-node/. Both
// are generated by `yarn build:wasm`; this catches one of them being stale.
test("browser and Node WASM builds contain the same algorithm", () => {
  const wasmFile = fileURLToPath(
    new URL("../../../backend/rust_wasm_module/pkg/rust_wasm_module_bg.wasm", import.meta.url)
  );
  initSync({ module: readFileSync(wasmFile) });
  expect(webAlgoVersion()).toBe(wasm.algo_version());
});
